const runnerBase = $env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = $env.AUTOMATION_RUNNER_TOKEN;
const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};
const weekAgo = Date.now() - 7 * 24 * 60 * 60 * 1000;
const items = Array.isArray($input.first().json.results) ? $input.first().json.results : [];
const completed = items.filter((item) => item.completed_at && new Date(item.completed_at).getTime() >= weekAgo);
const grouped = completed.reduce((acc, item) => {
  const bucket = acc[item.priority || 'none'] || [];
  bucket.push(item.name);
  acc[item.priority || 'none'] = bucket;
  return acc;
}, {});
const lines = ['# Release Notes', '', `Generated: ${new Date().toISOString()}`, ''];
for (const priority of Object.keys(grouped).sort()) {
  lines.push(`## ${priority}`);
  lines.push('');
  for (const name of grouped[priority]) {
    lines.push(`- ${name}`);
  }
  lines.push('');
}
if (completed.length === 0) {
  lines.push('No recently completed items were found.');
}
const reportRelativePath = `release-notes/${new Date().toISOString().replace(/[:]/g, '-')}.md`;
const writeResponse = await fetch(`${runnerBase}/reports/write`, {
  method: 'POST',
  headers,
  body: JSON.stringify({ relativePath: reportRelativePath, content: lines.join('\n') }),
});
if (!writeResponse.ok) throw new Error(`reports/write failed: ${writeResponse.status}`);
return [{ json: { completedCount: completed.length, reportRelativePath } }];
